rows[80000]={title={{27,2084460762},"황금 용매 새끼"},description={{140,1342962343},"실버문에서 용매 사육사들에게 한때 귀하게 여겨졌던 종입니다. 밤에는 포식자의 눈에 잘 띄기 때문에 어릴 때부터 주변 환경에 대한 경각심을 키우는 것이 중요합니다."}}
rows[80001]={title={{17,1381733991},"탈라시안 텐더"},description={{53,10681778},"이 나무는 언제나 춤추듯 깨어나요. 정말 행복한 작은 나무네요!"}}
rows[80003]={title={{16,722846021},"검은발여우"},description={{88,198717758},"추운 밤이면 이 동물들은 복슬복슬한 꼬리를 담요처럼 사용하여 따뜻하게 지냅니다."}}
rows[80004]={title={{13,1073471168},"장난꾸러기 원숭이"},description={{137,1499325445},"장난기 넘치는 성격과 귀여운 행동으로 가득한 이 아기 원숭이들은 아제로스에서의 모험을 더욱 즐겁게 만들어 줄 완벽한 동반자입니다."}}
rows[80006]={title={{16,744584573},"신비로운 정령"},description={{91,140799404},"어둠 속에서 이 작은 정령은 은은한 푸른빛을 무한히 발산합니다."}}
rows[80007]={title={{15,1307814434},"마법의 빗자루"},description={{120,1171456330},"하이 엘프 견습생이 만든 이 빗자루는 누군가 멈추는 방법을 알아낼 수만 있다면 엄청나게 유용할 것이다."}}
rows[80008]={title={{20,1338487459},"시간의 청동 원반"},description={{96,1521066241},"크로미가 시간의 통로 주변의 균열을 닫기 위해 당신에게 준 것이지만, 그 에너지는 어디로 가는 걸까요?"}}
rows[80010]={title={{8,1314394797},"자정"},description={{76,846402487},"한밤중에 달과 함께 (그리고 이 털북숭이 수염 난 마녀와 함께) 말을 타고 달려보세요!"}}
rows[80060]={title={{12,777042777},"전쟁의 문양"},description={{126,447524304},"더 이상 PvP 모드를 비활성화할 수 없지만, 모든 경험치 획득량이 증가합니다. 이 효과는 레벨 60 달성 후에도 지속됩니다."}}
