rows[83151]={title={{20,291004643},"블랙 스펙트럴 타이거"},description={{157,1406296554},"이 사나운 호랑이는 어둠의 기운에 휩싸여 있어 전장에서 공포의 대상이다. 이 호랑이를 타는 자는 그림자의 힘을 구현한다고 전해진다."}}
rows[83152]={title={{20,1315763655},"그린 스펙트럴 타이거"},description={{170,910127895},"희귀하고 찾기 힘든 탈것인 녹색 유령 호랑이는 숲의 정령들이 축복한 것이라고 전해집니다. 이 말을 타는 자는 자연과 특별한 교감을 나눌 수 있다고 합니다."}}
rows[83153]={title={{10,1153820569},"아이스 랩터"},description={{149,74580239},"이 날렵하고 민첩한 맹금류는 북극의 혹독하고 얼음으로 뒤덮인 환경에 적응했습니다. 날카로운 발톱과 이빨 덕분에 전투에서 강력한 탈것으로 활약할 수 있습니다."}}
