rows[83155]={title={{15,447124505},"붉은십자군 군마"},description={{70,808828834},"이는 적에게 공포심을 심어주려는 사람들이 흔히 이용하는 방식입니다."}}
rows[83156]={title={{18,284138614},"쿨 티란 군마"},description={{163,1564871883},"쿨 티란 군마는 튼튼하고 믿음직스러운 탈것으로, 전투를 위해 길러졌으며 위험을 두려워하지 않습니다. 거대한 몸집과 힘은 전투에서 막강한 아군이 되어줍니다."}}
rows[83157]={title={{16,515454262},"그레이메인 군마"},description={{165,324114044},"그레이메인 차저는 길네아인의 강인함과 회복력을 상징합니다. 윤기 나는 은빛 털과 번개처럼 빠른 속도는 길네아 병사들 사이에서 가장 인기 있는 말입니다."}}
rows[83158]={title={{12,830048094},"브라운 제브라"},description={{190,311920798},"브라운 제브라는 빠르고 발걸음이 안정적인 말로, 가장 험난한 지형도 쉽게 헤쳐나갈 수 있습니다. 줄무늬 털과 우아한 움직임 덕분에 모험가들 사이에서 인기 있는 선택입니다."}}
